api_examples:
Python (sync):
  for page in client.items().pages(page_size=100):
      process(page.items)

Python (resume):
  cursor = previous_run_cursor
  for page in client.items().pages(page_size=100, resume_from=cursor):
      process(page.items)

TypeScript (async iterator):
  for await (const page of client.items().pages({pageSize: 100})) {
    process(page.items)
  }

Go (channel style):
  pages := client.Items().Pages(ctx, Options{PageSize:100})
  for p := range pages {
    process(p.Items)
  }
